export function sourceProof(){const sources=PATHS.map(p=>{const b=fs.readFileSync(ROOT+'/'+p),parent=execFileSync('git',['show',PARENT+':'+p],{cwd:ROOT,maxBuffer:2*1024*1024});const binding=PARENT_BINDINGS.find(r=>r.path===p);assert.equal(hash(parent),binding.sha256);assert.equal(parent.length,binding.bytes);let t=b.toString();for(const e of INVERSES.filter(e=>e.path===p).reverse()){assert.equal(t.split(e.after).length,e.count+1,p+' inverse');t=t.split(e.after).join(e.before);}assert.deepEqual(Buffer.from(t),parent);return{path:p,bytes:b.length,sha256:hash(b)};});const newPath='tools/test-battery-overrun.mjs',b=fs.readFileSync(ROOT+'/'+newPath);assert.equal(spawnSync('git',['cat-file','-e',PARENT+':'+newPath],{cwd:ROOT,stdio:'ignore'}).status,128);sources.push({path:newPath,bytes:b.length,sha256:hash(b)});assert.equal(sources.length,67);assert.equal(new Set(sources.map(s=>s.path)).size,67);const changed=sources.filter(s=>{const p=PARENT_BINDINGS.find(r=>r.path===s.path);return !p||s.sha256!==p.sha256;}).length;assert.equal(changed,10);return{sources,sourceInverse:{all66ParentExact:true,parentBindings:PARENT_BINDINGS,changed:10,locked:57,newProbeAbsentInParent:true}};}
export async function verifyBatteryOverrunRecord(r){assert.equal(r.parent,PARENT);assert.deepEqual(r.sources,sourceProof().sources);assert.deepEqual(r.sourceInverse,sourceProof().sourceInverse);assert.deepEqual(r.componentBindings,COMPONENT_HASHES);const binary=(await load('binary')).module,codec=(await load('codec')).module,readers=(await load('readers')).module,controls=(await load('controls')).module;const data=binary.decodeEnvelope(r.canonical);assert.equal(hash(codec.typedText(data)),r.semanticRaw.sha256);assert.equal(Buffer.byteLength(codec.typedText(data)),r.semanticRaw.bytes);const categories=readers.challengeRows(data.rows);assert.deepEqual(r.categories,categories.map(({control,...c})=>c));assert.deepEqual(r.controls,categories.map(c=>c.control));assert.deepEqual(r.transport,controls.codecControls());assert.equal(r.categories.length,14);assert.equal(r.controls.length,14);assert.deepEqual(r.extraControls,supplemental(data.rows,readers,codec));return true;}
function supplemental(rows,readers,codec){const result=[];for(const [name,i,change] of [['source-order-declared',6,d=>d.sameBatchRows[0].sourceIds.reverse()],['physical-pool-counts',7,d=>{for(const r of d.rows)for(const s of [r.before,r.at,...r.post]){s.counts=[-1,-1,-1];s.used={US:-1,CS:-1,limbers:-1};}}]]){const d=structuredClone(rows[i]);change(d);let e;try{readers.verifySemantic(i,d);}catch(error){e=error;}assert.equal(e?.code,'ERR_ASSERTION');result.push({name,code:e.code,message:e.message.split('\n')[0],mutationSha256:hash(codec.typedText(d))});}return result;}
export async function runBatteryOverrun(){const source=sourceProof(),codec=(await load('codec')).module,binary=(await load('binary')).module,readers=(await load('readers')).module,controls=(await load('controls')).module;const rows=[];for(let i=0;i<14;i++){const text=execFileSync(process.execPath,[self,String(i)],{cwd:ROOT,encoding:'utf8',maxBuffer:16*1024*1024});rows.push(codec.restoreTyped(JSON.parse(text)));}const input={version:1,rows},canonical=binary.encodeEnvelope(input);assert.deepEqual(binary.decodeEnvelope(canonical),input);const categories=readers.challengeRows(rows),typed=codec.typedText(input),r={parent:PARENT,scope:'Actual CPU source67 overrun proof; no native/GPU/history/loot admission',...source,componentBindings:COMPONENT_HASHES,canonical,semanticRaw:{bytes:Buffer.byteLength(typed),sha256:hash(typed)},categories:categories.map(({control,...c})=>c),controls:categories.map(c=>c.control),transport:controls.codecControls(),extraControls:supplemental(rows,readers,codec),native:false};await verifyBatteryOverrunRecord(r);assert.deepEqual(sourceProof(),source);return r;}
const direct=process.argv[1]&&fs.existsSync(process.argv[1])&&fs.realpathSync(process.argv[1])===self;
if(direct){try{if(/^(?:[0-9]|1[0-3])$/.test(process.argv[2]||'')){await load('cases');}else{const r=await runBatteryOverrun(),line='BATTERY OVERRUN ACTUAL '+JSON.stringify(r);assert(Buffer.byteLength(line)<=4*1024*1024);console.log(line);console.log('BATTERY OVERRUN OK (14/14)');if(process.argv.includes('--prove-fail')){for(const c of r.controls)console.log('CAUGHT '+c.name+' '+c.code+' '+c.message);console.log('BATTERY OVERRUN CONTROLS '+JSON.stringify(r.controls));console.log('BATTERY OVERRUN MUTANTS CAUGHT (14/14; semantic readers)');}}}catch(e){console.error('BATTERY OVERRUN FAILED '+(e.code||e.name)+' '+e.message.split('\n')[0].slice(0,200));process.exitCode=1;}}
